package cn.luwneshacha.platform.storage;

import java.io.*;

/** Private object storage. Keys are generated by the submission module, never supplied by clients. */
public interface ObjectStorage {
  record StoredObject(InputStream stream, long size) implements AutoCloseable {
    @Override public void close() throws IOException { stream.close(); }
  }
  void put(String key, InputStream content, long size, String contentType) throws IOException;
  StoredObject get(String key) throws IOException;
  void deletePrefix(String prefix) throws IOException;
}
